{
  "cvars": {
    "ivs": [
      {
        "description": "Applicant gender indicator: 1 = female, 0 = male. Primary independent variable testing whether banks treat female applicants differently than male applicants.",
        "columns": [
          "female"
        ]
      }
    ],
    "dv": {
      "description": "Mortgage application outcome: 1 = accepted, 0 = denied. Binary dependent variable capturing whether the application was approved.",
      "columns": [
        "accept"
      ]
    },
    "controls": [
      {
        "description": "Applicant race indicator: 1 = Black, 0 = non-Black. Controls for racial differences in approval rates.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "black"
        ]
      },
      {
        "description": "Lender's mortgage-specific credit score (ordinal). Controls for creditworthiness as measured for mortgage evaluation.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "mortgage_credit"
        ]
      },
      {
        "description": "Applicant's consumer credit score (ordinal). Controls for consumer creditworthiness.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "consumer_credit"
        ]
      },
      {
        "description": "Indicator for prior bad credit history: 1 = has bad history, 0 = no bad history. Controls for credit problems that increase denial likelihood.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "bad_history"
        ]
      },
      {
        "description": "Payment-to-income ratio (PI_ratio). Controls for debt burden relative to income.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PI_ratio"
        ]
      },
      {
        "description": "Loan-to-value ratio of the requested mortgage. Controls for loan risk and collateral coverage.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "loan_to_value"
        ]
      },
      {
        "description": "Marital status: 1 = married, 0 = not married. Controls for household composition / combined income effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "married"
        ]
      },
      {
        "description": "Self-employment indicator: 1 = self-employed, 0 = not. Controls for employment type which can affect approval.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "self_employed"
        ]
      },
      {
        "description": "Housing expense ratio (housing_expense_ratio). Controls for existing housing costs relative to income.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "housing_expense_ratio"
        ]
      },
      {
        "description": "Indicator whether private mortgage insurance (PMI) was denied: 1 = denied PMI, 0 = was not denied. Controls for underwriting/insurance factors.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "denied_PMI"
        ]
      },
      {
        "description": "Applicant religiousness (ordinal). Included as an additional observed applicant characteristic (not central but available in dataset).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "religiousness"
        ]
      },
      {
        "description": "Occupation code (Hollingshead-based). Controls for socio-economic status related to occupation.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "occupation"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Prepare the dataset for modeling the effect of gender on mortgage approval.\n    - Coerce relevant columns to numeric\n    - Drop rows with missing values in the dependent, independent, or control variables\n    - Ensure binary indicators are integer-typed\n    Returns the cleaned dataframe with the exact column names used in the model.\n    \"\"\"\n    df = df.copy()\n\n    # Columns required for the analysis (IV, DV, and controls)\n    required_cols = [\n        'accept', 'female', 'black', 'mortgage_credit', 'consumer_credit', 'bad_history',\n        'PI_ratio', 'loan_to_value', 'married', 'self_employed', 'housing_expense_ratio',\n        'denied_PMI', 'religiousness', 'occupation'\n    ]\n\n    # Coerce to numeric where possible (this will set non-convertible to NaN)\n    for c in required_cols:\n        # preserve original values for non-numeric columns -- convert coercively\n        df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows with missing values in any required column\n    df = df.dropna(subset=required_cols).reset_index(drop=True)\n\n    # Ensure binary indicator columns are integer 0/1\n    for b in ['accept', 'female', 'black', 'bad_history', 'married', 'self_employed', 'denied_PMI']:\n        # round then cast to int to guard against floats like 0.0/1.0\n        df[b] = df[b].round().astype(int)\n\n    # Keep only the columns we will use in the model (cleaned)\n    # This also ensures the final dataframe contains exactly the column names listed in cvars\n    final_cols = required_cols\n    df = df[final_cols].copy()\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fit a logistic regression (binomial) model estimating the effect of applicant gender (female)\n    on mortgage acceptance, controlling for observed applicant and loan characteristics.\n\n    Model form (logit):\n        logit(P(accept=1)) = alpha + beta_female*female + sum(gamma_k * control_k)\n\n    Returns the fitted statsmodels LogitResults object. Also computes and prints odds ratios\n    and 95% confidence intervals for interpretation.\n    \"\"\"\n    import statsmodels.api as sm\n    import numpy as np\n\n    df = df.copy()\n\n    # Columns used in the model (must match transform output)\n    model_cols = [\n        'female', 'black', 'mortgage_credit', 'consumer_credit', 'bad_history',\n        'PI_ratio', 'loan_to_value', 'married', 'self_employed', 'housing_expense_ratio',\n        'denied_PMI', 'religiousness', 'occupation'\n    ]\n\n    # Ensure no missingness (transform should have dropped NA already, but be safe)\n    df = df.dropna(subset=['accept'] + model_cols)\n\n    X = df[model_cols]\n    X = sm.add_constant(X)\n    y = df['accept']\n\n    # Fit logistic regression\n    logit = sm.Logit(y, X)\n    results = logit.fit(disp=False)\n\n    # Calculate odds ratios and 95% CI for easier interpretation\n    params = results.params\n    conf = results.conf_int()\n    odds_ratios = np.exp(params)\n    conf_odds = np.exp(conf)\n\n    # Attach readable summary information to the results object (non-invasive)\n    try:\n        results.odds_ratios = odds_ratios\n        results.conf_odds = conf_odds\n    except Exception:\n        # If the results object is immutable in some environment, return a dict instead\n        return {\n            'fit': results,\n            'odds_ratios': odds_ratios,\n            'conf_odds': conf_odds\n        }\n\n    return results\n"
}

